        # If m is 0, we can simply assign consecutive scores starting from 10
        return list(range(10, 10 + n))

    # Try to construct a sequence that satisfies the conditions
    a = [0] * n
    a[0] = 1
    for i in range(1, n):
        a[i] = a[i - 1] + 1

    # Calculate the current balance
    current_balance = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if a[i] + a[j] == a[k]:
                    current_balance += 1

    # If the current balance is already m, return the sequence
    if current_balance == m:
        return a

    # If the current balance is less than m, try to increase it
    if current_balance < m:
        # Increase the last element until the balance reaches m
        while current_balance < m:
            a[-1] += 1
            for i in range(n):
                for j in range(i + 1, n):
                    for k in range(j + 1, n):
                        if a[i] + a[j] == a[k]:
                            current_balance += 1
            if current_balance == m:
                return a

    # If the current balance is more than m, try to decrease it
    if current_balance > m:
        # Decrease the last element until the balance reaches m
        while current_balance > m:
            a[-1] -= 1
            for i in range(n):
                for j in range(i + 1, n):
                    for k in range(j + 1):
                        if a[i] + a[j] == a[k]:
                            current_balance -= 1
            if current_balance == m:
                return a

    # If no valid score distribution is found, return -1
    return -1

